static void request_free(gpointer p) { Request *r=p;g_free(r->endpoint);g_free(r->model);if(r->key) { memset(r->key,0,strlen(r->key));g_free(r->key); }g_free(r->python);g_free(r->helper);g_free(r->question);g_free(r->context);g_free(r->base);g_free(r->history);g_free(r->location);insight_ai_answer_free(r->answer);g_free(r); }
