static void destroyed(GtkWidget *widget,gpointer p) { (void)widget;Assistant *a=p;a->closed=TRUE;if(a->cancel) g_cancellable_cancel(a->cancel); }
static void worker(GTask *task,gpointer object,gpointer p,GCancellable *cancel) { (void)object;Request *r=p;InsightAiRequest request={r->endpoint,r->model,r->key,r->question,r->context,r->base,r->history,r->location};GError *e=NULL;r->answer=insight_ai_request(r->python,r->helper,&request,cancel,&e);if(r->answer) g_task_return_boolean(task,TRUE);else g_task_return_error(task,e); }
