static void save_settings(Assistant *a) { GKeyFile *k=g_key_file_new();g_key_file_set_integer(k,"assistant","provider",gtk_combo_box_get_active(GTK_COMBO_BOX(a->provider)));g_key_file_set_string(k,"assistant","endpoint",gtk_entry_get_text(GTK_ENTRY(a->endpoint)));g_key_file_set_string(k,"assistant","model",gtk_entry_get_text(GTK_ENTRY(a->model)));g_key_file_set_string(k,"assistant","python",gtk_entry_get_text(GTK_ENTRY(a->python)));gsize n;gchar *data=g_key_file_to_data(k,&n,NULL),*path=settings_path();GFile *file=g_file_new_for_path(path);g_file_replace_contents(file,data,n,NULL,FALSE,G_FILE_CREATE_PRIVATE,NULL,NULL,NULL);g_object_unref(file);g_free(data);g_free(path);g_key_file_unref(k); }
