static void attach(GtkWidget *widget,gpointer p) { (void)widget;Assistant *a=p;if(a->busy) return;GeanyDocument *doc=document_get_current();if(!doc) return;gint n=SEND(doc->editor->sci,SCI_GETLENGTH,0,0);if(n<0 || n>131072) { status(a,"Attached source is limited to 128 KiB.");return; }gchar *code=sci_get_contents(doc->editor->sci,-1);if(memchr(code,0,n) || !g_utf8_validate(code,n,NULL)) { g_free(code);status(a,"Attach UTF-8 source without NUL bytes.");return; }g_free(a->base);g_free(a->location);a->base=code;a->location=g_strdup(doc->file_name ? doc->file_name:"untitled");a->document=doc->id;g_string_truncate(a->history,0);insight_ai_answer_free(a->response);a->response=NULL;gchar *label=g_strdup_printf("%s — %s (%d bytes)",insight_tr("Attached source"),a->location,n);status(a,label);g_free(label);controls(a); }
